const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function getInfoAsync(eeObject) {
  return await new Promise((resolve, reject) => {
    eeObject.getInfo((info, err) => {
      if (err) reject(err);
      else resolve(info);
    });
  });
}

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const lon = -122.555169;
    const lat = 40.190004;
    const pt = ee.Geometry.Point([lon, lat]);
    const region = pt.buffer(10000); // 10 km
    const dayStart = ee.Date('2020-08-25');
    const dayEnd = ee.Date('2020-08-26');
    const monthStart = ee.Date('2020-08-01');
    const monthEnd = ee.Date('2020-09-01');

    // 2. Try datasets likely containing column mass of black carbon
    const datasets = [
      {id: 'NASA/GSFC/MERRA/M2T1NXAER', start: dayStart, end: dayEnd, label: 'MERRA-2 Hourly AER'},
      {id: 'NASA/GSFC/MERRA/M2TMNXAER', start: monthStart, end: monthEnd, label: 'MERRA-2 Monthly AER'}
    ];
    const candidateBands = ['BCCMASS']; // Column mass density of black carbon (kg m-2)

    let chosen = null;
    for (let ds of datasets) {
      let col = ee.ImageCollection(ds.id).filterDate(ds.start, ds.end);
      const n = await getInfoAsync(col.size());
      if (n === 0) {
        console.log(`${ds.label} images: 0`);
        continue;
      }
      const bands = await getInfoAsync(col.first().bandNames());
      const foundBand = bands && bands.find(b => candidateBands.includes(b));
      if (foundBand) {
        chosen = {col, id: ds.id, label: ds.label, band: foundBand, n};
        break;
      } else {
        console.log(`${ds.label} images: ${n}, but no BCCMASS band`);
      }
    }

    if (!chosen) {
      console.log('No dataset with BCCMASS found for the period.');
      console.log('D');
      return;
    }

    console.log(`Dataset: ${chosen.label} (${chosen.id})`);
    console.log(`Band: ${chosen.band}, Images: ${chosen.n}`);

    // 3. Processing: Convert to mg/m^2 and average over period
    const mgCol = chosen.col.select(chosen.band).map(img =>
      img.multiply(1e6).rename('bc_mg_m2') // kg/m^2 -> mg/m^2
    );
    const meanImg = mgCol.mean();

    // 4. Valid pixel count and mean over region
    const scale = 25000; // 25 km for reanalysis grid
    const countDict = await getInfoAsync(meanImg.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: scale,
      maxPixels: 1e9
    }));
    const count = countDict ? countDict['bc_mg_m2'] : null;
    console.log(`Valid pixels: ${count !== null ? count : 0} (scale=${scale} m)`);

    if (!count || count === 0) {
      console.log('C2');
      return;
    }

    const meanDict = await getInfoAsync(meanImg.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: region,
      scale: scale,
      maxPixels: 1e9
    }));
    const val = meanDict ? meanDict['bc_mg_m2'] : null;

    if (val === null || !isFinite(val)) {
      console.log('C3');
      return;
    }

    console.log(`BC mean (mg/m^2) on 2020-08-25: ${val.toFixed(2)}`);

    // 5. Final Answer: > 12 mg/m^2 ?
    if (val > 12) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log(`Error: ${String(err).slice(0, 200)}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
